async function viewSettings() {

  const s = await api('GET', '/api/admin/settings');

  const now = new Date();

  const fy = now.getFullYear() + 543 + (now.getMonth() >= 9 ? 1 : 0);          // ปีงบประมาณ พ.ศ. (ต.ค.–ก.ย.)

  const fmtAt = (iso) => new Date(iso).toLocaleString('th-TH', { timeZone: 'Asia/Bangkok', dateStyle: 'medium', timeStyle: 'short' });

  const last = s.last_auto_result

    ? `ครั้งล่าสุด ${fmtAt(s.last_auto_result.at)} · ${s.last_auto_result.errors ? `<span class="text-danger">ผิดพลาด ${s.last_auto_result.errors} จาก ${s.last_auto_result.total} รายการ</span>` : '<span class="text-success">สำเร็จทั้งหมด</span>'}`

    : 'ยังไม่เคยดึงอัตโนมัติ';

  $('#view').innerHTML = `<div class="card" style="max-width:560px"><div class="card-body">

    <h2 class="h6 mb-3">ข้อมูลที่ดึง</h2>

    <div class="row g-3 mb-2">

      <div class="col-6"><label class="form-label">รหัสจังหวัด (2 หลัก)</label><input id="sp" class="form-control" maxlength="2" value="${esc(s.province)}"></div>

      <div class="col-6"><label class="form-label">ดึงข้อมูลย้อนหลัง (ปี)</label><input id="sy" type="number" min="1" max="15" class="form-control" value="${esc(s.years_back)}"></div>

    </div>

    <div class="small text-muted mb-4">ปีเป็นปีงบประมาณ พ.ศ. (ต.ค.–ก.ย.) ปีปัจจุบันคือ ${fy} เช่น 5 ปี = ${[...Array(5)].map((_, i) => fy - 4 + i).join(', ')} (ปีงบใหม่ช่วงแรกอาจยังไม่มีข้อมูล)<br>เปลี่ยนจังหวัดแล้วต้องกด "ดึงข้อมูลทุกรายงาน" ใหม่ ข้อมูลของจังหวัดเดิมจะยังอยู่ในฐาน</div>

    <h2 class="h6 mb-3">ดึงข้อมูลอัตโนมัติรายวัน</h2>

    <div class="d-flex flex-wrap align-items-center gap-3 mb-2">

      <div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" role="switch" id="se" ${s.sync_enabled ? 'checked' : ''}><label class="form-check-label" for="se">เปิดใช้งาน</label></div>

      <div class="d-flex align-items-center gap-2"><label class="form-label m-0" for="st">เวลา (เวลาไทย)</label><input id="st" type="time" class="form-control" style="width:8rem" value="${esc(s.sync_time)}"></div>

    </div>

    <div class="small text-muted mb-4">${last}<br>ถ้าเซิร์ฟเวอร์ปิดอยู่ตอนถึงเวลา จะดึงให้ทันทีที่เปิดขึ้นมาในวันเดียวกัน ใช้เวลาประมาณ 4–6 นาที และดูความคืบหน้าได้ที่แท็บ "ดึงข้อมูล / Log"</div>

    <button class="btn btn-primary" id="save">บันทึก</button></div></div>

    <div class="card mt-3" style="max-width:560px"><div class="card-body">

      <h2 class="h6 mb-2">อีเมลส่งรหัสเข้าสู่ระบบ</h2>

      <div class="mb-2">โหมด: <span class="badge ${s.mail.ready ? 'text-bg-success' : 'text-bg-warning'}">${esc(s.mail.mode)}</span>

        ${s.mail.ready ? '<span class="small text-success">พร้อมส่งจริง</span>' : '<span class="small">ยังไม่ส่งจริง — รหัสจะพิมพ์ลงบันทึกของเซิร์ฟเวอร์ (ใช้ได้เฉพาะเครื่องพัฒนา)</span>'}</div>

      <div class="small text-muted mb-3">ตั้งค่าที่ตัวแปรสภาพแวดล้อมของเซิร์ฟเวอร์ (ไม่เก็บในหน้านี้เพื่อความปลอดภัย): <span class="src">MAIL_MODE=resend</span>, <span class="src">RESEND_API_KEY</span>, <span class="src">RESEND_FROM_EMAIL</span> (แบบเดียวกับ dmyst) หรือ <span class="src">MAIL_MODE=smtp</span> ดูรายละเอียดใน docs/DEPLOY.md</div>

      <button class="btn btn-outline-primary" id="mailtest">ส่งอีเมลทดสอบถึงฉัน</button>

    </div></div>`;

  // สถิติผู้เข้าชมแดชบอร์ด 14 วันล่าสุด

  const vis = await api('GET', '/api/admin/visits?days=14');

  const maxV = Math.max(1, ...vis.days.map((d) => d.views));

  const dayTh = (d) => new Date(`${d}T00:00:00+07:00`).toLocaleDateString('th-TH', { timeZone: 'Asia/Bangkok', day: 'numeric', month: 'short', year: 'numeric' });

  $('#view').insertAdjacentHTML('beforeend', `<div class="card mt-3" style="max-width:560px"><div class="card-body">

    <h2 class="h6 mb-2">สถิติผู้เข้าชมหน้าแดชบอร์ด</h2>

    <div class="small text-muted mb-2">วันนี้ <b>${nf(vis.summary.today.visitors)}</b> คน (เปิดดู ${nf(vis.summary.today.views)} ครั้ง) · สะสม <b>${nf(vis.summary.total.visitors)}</b> คน-วัน, ${nf(vis.summary.total.views)} ครั้ง${vis.summary.since ? ` · นับตั้งแต่ ${dayTh(vis.summary.since)}` : ''}</div>

    <table class="table table-sm mb-2"><thead class="table-light"><tr><th>วันที่</th><th class="text-end">ผู้เข้าชม</th><th class="text-end">เปิดดู (ครั้ง)</th><th style="width:35%"></th></tr></thead>

    <tbody>${vis.days.map((d) => `<tr><td>${dayTh(d.day)}</td><td class="text-end">${nf(d.visitors)}</td><td class="text-end">${nf(d.views)}</td><td><div style="height:8px;border-radius:4px;background:var(--opc-primary);width:${Math.max(3, Math.round((d.views / maxV) * 100))}%"></div></td></tr>`).join('') || '<tr><td colspan="4" class="text-muted">ยังไม่มีข้อมูล (ไม่นับการเปิดจากเครื่องพัฒนา localhost และบอท)</td></tr>'}</tbody></table>

    <div class="small text-muted">ผู้เข้าชม = นับคนละ 1 ครั้งต่อวัน · ไม่เก็บ IP ดิบ ใช้ค่าแฮชชั่วคราวที่ลบทิ้งใน 2 วัน</div></div></div>`);

  $('#mailtest').onclick = () => run(async () => {

    const j = await api('POST', '/api/admin/mail/test', {});

    toast(j.ready ? `ส่งอีเมลทดสอบถึง ${j.to} แล้ว ตรวจกล่องจดหมาย` : `โหมด ${j.mode}: ยังไม่ได้ส่งจริง (ดูบันทึกเซิร์ฟเวอร์)`, j.ready ? 'success' : 'warning');

  });

  $('#save').onclick = () => run(async () => {

    await api('PUT', '/api/admin/settings', { province: $('#sp').value, years_back: $('#sy').value, sync_enabled: $('#se').checked, sync_time: $('#st').value });

    toast('บันทึกแล้ว');

  });

}

sync_fn:
async function viewSync() {

  const [st, log] = await Promise.all([api('GET', '/api/admin/sync/status'), api('GET', '/api/admin/sync/log?limit=100')]);

  const badge = { ok: 'success', error: 'danger', running: 'primary', 'empty-kept': 'warning' };

  $('#view').innerHTML = `

    <div class="card mb-3"><div class="card-body">

      <div class="d-flex flex-wrap gap-2 align-items-center">

        <button class="btn btn-primary" id="all" ${st.running ? 'disabled' : ''}>ดึงข้อมูลทุกรายงาน</button>

        <span class="text-muted small">ดึงตามจังหวัดและจำนวนปีย้อนหลังในแท็บตั้งค่า (ใช้เวลาราว 3–5 นาที)</span>

      </div>

      <div id="prog" class="mt-3"></div>

    </div></div>

    <div class="table-responsive bg-white border rounded"><table class="table table-sm table-hover mb-0">

      <thead class="table-light"><tr><th>เวลา</th><th>รายงาน</th><th>ปี</th><th>สถานะ</th><th class="text-end">แถว</th><th>ข้อความ</th></tr></thead>

      <tbody>${log.map((l) => `<tr><td class="small text-nowrap">${fmt(l.started_at)}</td><td>${esc(l.name)} <span class="src text-muted">${esc(l.source_table)}</span></td><td>${esc(l.year)}</td>

        <td><span class="badge text-bg-${badge[l.status] || 'secondary'}">${esc(l.status)}</span></td><td class="text-end">${nf(l.row_count)}</td><td class="small text-danger">${esc(l.error || '')}</td></tr>`).join('') || '<tr><td colspan="6" class="text-center text-muted py-3">ยังไม่มีประวัติ</td></tr>'}</tbody></table></div>`;

  $('#all').onclick = () => startSync({ all: true });

  showProgress(st);

  clearInterval(poll);

  if (st.running) poll = setInterval(async () => {

    const s = await api('GET', '/api/admin/sync/status').catch(() => null);

    if (!s) return;

    showProgress(s);

    if (!s.running) { clearInterval(poll); if (current === 'sync') run(viewSync); }

  }, 2000);

}

start_sync_fn:
async function startSync(body) {

  await run(async () => {

    const j = await api('POST', '/api/admin/sync', body);

    toast(`เริ่มดึงข้อมูล ${j.total} รายการ (ปี ${j.years.join(', ')})`);

    switchTab('sync');

  });

}

report_form_fn:
function reportForm(r) {

  const isNew = !r;

  r = r || { name: '', source_table: '', category_id: null, is_active: true, sort_order: 0, goal_pct: null, higher_is_better: true, num_col: 'result', den_col: 'target', show_pct: true, description: '' };

  openModal(isNew ? 'เพิ่มรายงาน' : 'แก้ไขรายงาน', `

    <div class="mb-3"><label class="form-label">ชื่อรายงาน</label><input id="rn" class="form-control" value="${esc(r.name)}"></div>

    <div class="row g-3 mb-3">

      <div class="col-md-7"><label class="form-label">ชื่อตารางจาก API (tableName)</label>

        <div class="input-group"><input id="rt" class="form-control src" placeholder="เช่น s_aged9" value="${esc(r.source_table)}"><button class="btn btn-outline-secondary" id="rtest" type="button">ทดสอบดึง</button></div></div>

      <div class="col-md-5"><label class="form-label">หมวดหมู่</label><select id="rc" class="form-select">${catOptions(r.category_id)}</select></div>

    </div>

    <div class="row g-3 mb-3">

      <div class="col-md-4"><label class="form-label">ลำดับ</label><input id="ro" type="number" class="form-control" value="${esc(r.sort_order)}"></div>

      <div class="col-md-4 d-flex align-items-end"><div class="form-check"><input id="ra" type="checkbox" class="form-check-input" ${r.is_active ? 'checked' : ''}><label class="form-check-label" for="ra">เปิดใช้งาน</label></div></div>

    </div>

    <hr>

    <div class="row g-3 mb-3">

      <div class="col-md-3"><label class="form-label">เป้าหมาย (%)</label><input id="rg" type="number" step="0.1" min="0" class="form-control" placeholder="ไม่ตั้ง" value="${r.goal_pct ?? ''}"></div>

      <div class="col-md-5"><label class="form-label">ทิศทางที่ดี</label><select id="rh" class="form-select"><option value="1" ${r.higher_is_better ? 'selected' : ''}>ยิ่งสูงยิ่งดี (≥ เป้า)</option><option value="0" ${r.higher_is_better ? '' : 'selected'}>ยิ่งต่ำยิ่งดี (≤ เป้า)</option></select></div>

      <div class="col-md-4 d-flex align-items-end"><div class="form-check"><input id="rp" type="checkbox" class="form-check-input" ${r.show_pct ? 'checked' : ''}><label class="form-check-label" for="rp">แสดงเป็นร้อยละ (ตัวตั้ง ÷ ตัวหาร)</label></div></div>

    </div>

    <div class="row g-3 mb-3">

      <div class="col-md-6"><label class="form-label">คอลัมน์ตัวตั้ง (A)</label><input id="rnum" class="form-control src" value="${esc(r.num_col)}"></div>

      <div class="col-md-6"><label class="form-label">คอลัมน์ตัวหาร (B)</label><input id="rden" class="form-control src" value="${esc(r.den_col)}"></div>

      <div class="form-text">ดูชื่อคอลัมน์และความหมายได้ที่ปุ่ม "คอลัมน์" ในตารางรายงาน รวมหลายคอลัมน์ได้ด้วยเครื่องหมาย + เช่น <span class="src">result1+result2+result3+result4</span> (ใช้กับรายงานรายไตรมาส/รายอายุ/รายเดือน) ถ้าไม่เปิดแสดงเป็นร้อยละ แดชบอร์ดจะแสดงจำนวนของคอลัมน์ตัวตั้ง (หรือตัวหารถ้าไม่มีตัวตั้ง)</div>

    </div>

    <div class="mb-3"><label class="form-label">คำอธิบาย / นิยามตัวชี้วัด</label><textarea id="rd" rows="3" class="form-control">${esc(r.description || '')}</textarea></div>

    <div id="rprev"></div>`, [

    { label: 'ยกเลิก', close: true },

    { label: 'บันทึก', cls: 'primary', onClick: async () => {

      const body = { name: $('#rn').value, source_table: $('#rt').value, category_id: $('#rc').value || null, sort_order: $('#ro').value, is_active: $('#ra').checked,

        goal_pct: $('#rg').value, higher_is_better: $('#rh').value === '1', show_pct: $('#rp').checked, num_col: $('#rnum').value, den_col: $('#rden').value, description: $('#rd').value };

      await api(isNew ? 'POST' : 'PUT', isNew ? '/api/admin/reports' : `/api/admin/reports/${r.id}`, body);

      modal.hide(); toast('บันทึกแล้ว'); viewReports();

    } },

  ]);

  $('#rtest').onclick = () => run(async () => {

    $('#rprev').innerHTML = '<div class="text-muted small">กำลังดึงตัวอย่าง…</div>';

    try {

      const j = await api('POST', '/api/admin/reports/test', { source_table: $('#rt').value });

      $('#rprev').innerHTML = `<div class="alert alert-success py-2 small mb-2">พบข้อมูล ${nf(j.total)} แถว (ปี ${esc(j.year)} จังหวัด ${esc(j.province)}) — ${j.columns.length} คอลัมน์</div>

        <pre class="sample border rounded p-2 bg-light">${esc(JSON.stringify(j.sample, null, 1))}</pre>`;

    } catch (e) { $('#rprev').innerHTML = `<div class="alert alert-danger py-2 small">${esc(e.message)}</div>`; }

  });

}
